using MicroEngine.Core;
using MicroEngine.Input;
using MicroEngine.NativeChecks;
using MicroEngine.Sdl;
using SDL;
using static SDL.SDL3;

namespace MicroEngine.Desktop.Tests;

/// <summary>
/// The SDL keyboard path end to end on Linux, as the raylib one is checked (MicroEngine.Raylib.Tests, KeyboardTests):
/// key events are generated by the X server (XTEST, as a physical keyboard would), SDL receives them in a visible
/// window, and the engine reads them through SdlInput and InputMap, frame by frame as the game loop does.
/// </summary>
[TestClass]
[TestCategory("Native")]
[OSCondition(OperatingSystems.Linux, IgnoreMessage = "Keyboard injection uses the X server's XTEST extension.")]
public sealed unsafe class SdlKeyboardTests
{
    private XTest? _x;
    private SdlPlatform? _platform;
    private readonly InputMap _map = new InputMap().Bind("jump", Key.Space).Bind("left", Key.Left);

    [TestInitialize]
    public void Open()
    {
        _x = XTest.Open(out var missing);
        Native.Require(_x is not null, missing);
        // A visible window (keyboard focus needs one), driven by the test's frames rather than paced by the display.
        try { _platform = new SdlPlatform(new PlatformRequest(new GameSettings("keyboard test", 160, 90, 2)) { FixedStep = true, Mute = true }); }
        catch (InvalidOperationException e) { Native.Require(false, $"SDL cannot open a window here: {e.Message}"); }
        for (int i = 0; i < 5; i++) Frame();
        using var windows = SDL_GetWindows();
        Assert.IsTrue(windows is { Count: > 0 }, $"SDL lists the game's window ({SDL_GetError()}).");
        int x, y;
        Assert.IsTrue(SDL_GetWindowPosition(windows[0], &x, &y), SDL_GetError());
        // With the pointer over the window it has the keyboard focus (XTest.MovePointer).
        _x!.MovePointer(x + 160, y + 90);
        for (int i = 0; i < 5; i++) Frame();
    }

    [TestCleanup]
    public void Close()
    {
        _platform?.Dispose();
        _x?.Dispose();
    }

    private (bool Down, bool Pressed, bool Released) Frame()
    {
        _platform!.PollEvents(); // SDL reads the window's events here
        _map.Sample(_platform.Input);
        var state = (_map.Down("jump"), _map.Pressed("jump"), _map.Released("jump"));
        _map.EndUpdate();
        _platform.BeginFrame();
        _platform.EndFrame();
        Thread.Sleep(5);
        return state;
    }

    private void Send(nint keysym, bool press) => _x!.Key(keysym, press);

    private List<(bool Down, bool Pressed, bool Released)> Frames(int count) => [.. Enumerable.Range(0, count).Select(_ => Frame())];

    [TestMethod]
    public void A_held_key_is_pressed_once_stays_down_and_is_released()
    {
        Send(XTest.XkSpace, press: true);
        var held = Frames(20);
        int first = held.FindIndex(f => f.Down);
        Assert.IsTrue(first is >= 0 and <= 3, $"The key reached the engine within a few frames (frame {first}).");
        Assert.AreEqual(1, held.Count(f => f.Pressed), "One press edge for one key press.");
        Assert.IsTrue(held.Skip(first).All(f => f.Down), "Down on every frame while held.");
        Assert.IsFalse(held.Any(f => f.Released));

        Send(XTest.XkSpace, press: false);
        var after = Frames(10);
        int released = after.FindIndex(f => f.Released);
        Assert.IsTrue(released is >= 0 and <= 3, $"Released within a few frames (frame {released}).");
        Assert.AreEqual(1, after.Count(f => f.Released), "One release edge.");
        Assert.IsFalse(after.Skip(released).Any(f => f.Down), "Up after the release.");
    }

    [TestMethod]
    public void A_tap_shorter_than_a_frame_is_still_seen_once()
    {
        Send(XTest.XkSpace, press: true);
        Send(XTest.XkSpace, press: false); // both edges arrive before SDL polls: its keyboard state never shows the key down
        var frames = Frames(15);
        Assert.AreEqual(1, frames.Count(f => f.Pressed), "The tap counts as one press (SdlInput keeps unread taps).");
        Assert.AreEqual(1, frames.Count(f => f.Released), "And is released right after.");
        Assert.IsFalse(frames[^1].Down);
    }

    [TestMethod]
    public void Two_held_keys_are_independent()
    {
        Send(XTest.XkLeft, press: true);
        Frames(4);
        Assert.IsTrue(_map.Down("left"));
        Assert.IsFalse(_map.Down("jump"), "Only the key that was pressed.");
        Send(XTest.XkSpace, press: true);
        Frames(4);
        Assert.IsTrue(_map.Down("left") && _map.Down("jump"));
        Send(XTest.XkLeft, press: false);
        Frames(4);
        Assert.IsFalse(_map.Down("left"));
        Assert.IsTrue(_map.Down("jump"), "Releasing one key leaves the other held.");
        Send(XTest.XkSpace, press: false);
        Frames(4);
        Assert.IsFalse(_map.Down("jump"));
    }
}
